package com.example.stats.repository;

import com.example.stats.dto.UsageSummaryDto;
import java.sql.Timestamp;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.List;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class StatsRepositoryImpl implements StatsRepository {
    private static final Logger logger = LoggerFactory.getLogger(StatsRepositoryImpl.class);
    private final JdbcTemplate jdbcTemplate;

    public StatsRepositoryImpl(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public List<UsageSummaryDto> getUsageSummaryLast7Days() {
        try {
            Instant cutoff = Instant.now().minus(7, ChronoUnit.DAYS);
            String sql = ""
                + "SELECT account_id, COUNT(*) AS total_requests, COUNT(DISTINCT user_id) AS active_users "
                + "FROM requests "
                + "WHERE created_at >= ? "
                + "GROUP BY account_id";
            return jdbcTemplate.query(
                sql,
                new Object[] { Timestamp.from(cutoff) },
                (rs, rowNum) -> new UsageSummaryDto(
                    rs.getString("account_id"),
                    rs.getLong("total_requests"),
                    rs.getLong("active_users")
                )
            );
        } catch (Exception e) {
            logger.error("Failed to query usage summary for last 7 days", e);
            throw e;
        }
    }
}
